WITH base AS (SELECT *, ROUND(quantity, 0) quantity_rounded FROM order_items WHERE product_id IS NOT NULL AND order_id IN (25, 29)), agg AS (SELECT CASE WHEN quantity_rounded >= 79 THEN 'high' WHEN quantity_rounded >= 27 THEN 'mid' ELSE 'low' END quantity_rounded_bucket, CASE WHEN unit_price >= 330 THEN 'high' WHEN unit_price >= 140 THEN 'mid' ELSE 'low' END unit_price_bucket, MIN(unit_price) min_unit_price, ROUND(AVG(unit_price), 2) avg_unit_price FROM base GROUP BY CASE WHEN quantity_rounded >= 79 THEN 'high' WHEN quantity_rounded >= 27 THEN 'mid' ELSE 'low' END, CASE WHEN unit_price >= 330 THEN 'high' WHEN unit_price >= 140 THEN 'mid' ELSE 'low' END) SELECT quantity_rounded_bucket, unit_price_bucket, min_unit_price, avg_unit_price FROM agg WHERE avg_unit_price >= 20 ORDER BY min_unit_price DESC, unit_price_bucket, quantity_rounded_bucket LIMIT 20
